	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	return js
}

const (
	// Bucket is the regional KV bucket holding the region's report.
	Bucket    = "TS_OCI_COST"
	reportKey = "report"
	// maxReportBytes bounds a stored report well above the largest one
	// Validate accepts, so a corrupt value cannot exhaust memory.
	maxReportBytes = 64 << 10
)

// ErrNoReport means no report has been written yet.
var ErrNoReport = errors.New("no OCI cost report yet")

// Store is the region's replicated report.
type Store struct{ kv jetstream.KeyValue }

// OpenStore opens the region's report bucket. Replicas keep the report
// readable through a leader failover, which is when the next read matters.
func OpenStore(ctx context.Context, js jetstream.JetStream, replicas int) (*Store, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI cost store requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: Bucket, History: 1,
		MaxValueSize: maxReportBytes, MaxBytes: 1 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return nil, fmt.Errorf("open OCI cost store: %w", err)
	}
	return &Store{kv: kv}, nil
}

// Put replaces the report. An invalid report is refused before it reaches
// the bucket, so readers never see one.
func (s *Store) Put(ctx context.Context, report Report) error {
	if err := report.Validate(); err != nil {
		return fmt.Errorf("write OCI cost report: %w", err)
	}
	wire, err := protocol.EncodeJSON(report)
	if err == nil {
		_, err = s.kv.Put(ctx, reportKey, wire)
	}
	if err != nil {
		return fmt.Errorf("write OCI cost report: %w", err)
	}
	return nil
}

// Report returns the stored report, or ErrNoReport before the first Put.
func (s *Store) Report(ctx context.Context) (Report, error) {
	entry, err := s.kv.Get(ctx, reportKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Report{}, ErrNoReport
	}
	if err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	var report Report
	if err := protocol.DecodeStrict(entry.Value(), &report, maxReportBytes); err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	if err := report.Validate(); err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	return report, nil
}

const (
	// Version is the report's wire version.
	Version = 1
	// UsageLag is how long OCI usage data may take to arrive: a day counts
	// as complete once it ended at least this long ago.
	UsageLag = 48 * time.Hour
	// RateDays is how many complete days the daily rate averages.
	RateDays = 7
	// MaxReportAge is how long a report may stand in for failed reads.
	MaxReportAge = 6 * time.Hour

	// ComponentTag is the freeform tag the component lines group by.
	ComponentTag = "terrascale-component"
	// RegionTag is the freeform tag holding the resource's region.
	RegionTag = "terrascale-region"

	maxDays  = 64
	maxLines = 64
	// maxCents bounds an amount; more is a corrupt answer, not a bill.
	maxCents     = 1 << 40
	maxNameBytes = 64
	// maxUnitPrice bounds one SKU unit's price in currency units, as maxCents bounds an amount.
	maxUnitPrice = 1e6
	day          = 24 * time.Hour
)

// Components are the values of ComponentTag. Cost under any other value
// counts as untagged.
var Components = []string{"controller", "terrabase", "node-pool", "apps", "network", "releases", "images",
	"disaster-recovery", "storage"}

var (
	cellPattern     = regexp.MustCompile(`^[a-z][a-z0-9-]{0,30}$`)
	currencyPattern = regexp.MustCompile(`^[A-Z]{3}$`)
	// ErrInvalidReport marks a report that fails Validate.
	ErrInvalidReport = errors.New("invalid OCI cost report")
)

// Day is one UTC day's cost.
type Day struct {
	Day   time.Time `json:"day"`
	Cents uint64    `json:"cents"`
}

// Line is one service's or component's month-to-date cost.
type Line struct {
	Name  string `json:"name"`
	Cents uint64 `json:"cents"`
}

// Price is one SKU's unit price in the region: what it billed over what it
// metered in the rate window. Always Free usage prices at zero.
type Price struct {
	SKU     string  `json:"sku"`
	PerUnit float64 `json:"per_unit"`
}

// Report is one OCI region's cost as the Usage API last answered it.
// Amounts are whole cents of Currency, rounded up; credits count as zero.
type Report struct {
	Version   int    `json:"version"`
	Cell      string `json:"cell"`
	OCIRegion string `json:"oci_region"`
	// Currency is empty when OCI reported no cost at all.
	Currency   string    `json:"currency,omitempty"`
	ObservedAt time.Time `json:"observed_at"`
	// Through ends the last complete day.
	Through time.Time `json:"through"`
	// Days are the days with usage, oldest first, from the rate window or
	// the month's first day, whichever is earlier; the newest are partial.
	Days []Day `json:"days,omitempty"`
	// Services and Components are this month's lines, costliest first.
	// Components hold only tagged cost; the rest is untagged.
	Services   []Line `json:"services,omitempty"`
	Components []Line `json:"components,omitempty"`
	// Prices are sorted by SKU; a SKU absent from them has no usage yet.
	Prices []Price `json:"prices,omitempty"`
}

// Empty reports whether OCI answered without a single day of usage.
func (r Report) Empty() bool { return len(r.Days) == 0 }

// Validate bounds the report and checks its order, so a reader can trust
// any report it decodes.
func (r Report) Validate() error {
	switch {
	case r.Version != Version:
		return fmt.Errorf("%w: version %d", ErrInvalidReport, r.Version)
	case !cellPattern.MatchString(r.Cell) || r.OCIRegion == "" || len(r.OCIRegion) > maxNameBytes:
		return fmt.Errorf("%w: cell and OCI region are required", ErrInvalidReport)
	case r.Currency != "" && !currencyPattern.MatchString(r.Currency):
		return fmt.Errorf("%w: currency %q", ErrInvalidReport, r.Currency)
	case r.ObservedAt.IsZero() || !midnight(r.Through) || r.Through.After(r.ObservedAt):
		return fmt.Errorf("%w: needs an observation time after a UTC-midnight through", ErrInvalidReport)
	case len(r.Days) > maxDays || len(r.Services) > maxLines || len(r.Components) > maxLines || len(r.Prices) > maxLines:
		return fmt.Errorf("%w: more than %d days or %d lines", ErrInvalidReport, maxDays, maxLines)
	}
	var total uint64
	for index, entry := range r.Days {
		if !midnight(entry.Day) || index > 0 && !r.Days[index-1].Day.Before(entry.Day) || entry.Cents > maxCents {
			return fmt.Errorf("%w: days must be sorted unique UTC midnights within bounds", ErrInvalidReport)
		}
		total += entry.Cents
	}
	for _, lines := range [][]Line{r.Services, r.Components} {
		for index, line := range lines {
			if line.Name == "" || len(line.Name) > maxNameBytes || line.Cents > maxCents ||
				slices.ContainsFunc(lines[:index], func(other Line) bool { return other.Name == line.Name }) {
				return fmt.Errorf("%w: lines need unique bounded names", ErrInvalidReport)
			}
			total += line.Cents
		}
	}
	for _, line := range r.Components {
		if !slices.Contains(Components, line.Name) {
			return fmt.Errorf("%w: unknown component %q", ErrInvalidReport, line.Name)
		}
	}
	for index, price := range r.Prices {
		if price.SKU == "" || len(price.SKU) > maxNameBytes || index > 0 && r.Prices[index-1].SKU >= price.SKU ||
			!(price.PerUnit >= 0 && price.PerUnit <= maxUnitPrice) {
			return fmt.Errorf("%w: prices need sorted unique SKUs and unit prices within bounds", ErrInvalidReport)
		}
	}
	if r.Currency == "" && total != 0 {
		return fmt.Errorf("%w: cost without a currency", ErrInvalidReport)
	}
	return nil
}

func midnight(at time.Time) bool {
	return !at.IsZero() && at.Location() == time.UTC && at.Equal(at.Truncate(day))
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

