// OCITags is the Resource Search and per-type update view of one OCI region.
// Compartments, when set, scope the search; a controller leaves it empty and
// its IAM limits what it sees.
type OCITags struct {
	Compartments []string
	search       searchAPI
	compute      computeAPI
	blocks       blockAPI
	objects      objectAPI
	balancers    balancerAPI
	namespace    string // cached Object Storage namespace
}

const (
	searchLimit    = 1000
	maxSearchPages = 20
	// searchQuery lists the billable types; the lifecycle clause drops what
	// OCI has already removed.
	searchQuery = "query instance, bootvolume, volume, bootvolumebackup, volumebackup, image, bucket, loadbalancer " +
		"resources where lifecycleState != 'TERMINATED' && lifecycleState != 'TERMINATING' && lifecycleState != 'DELETED'"
)

// compartmentPattern keeps a compartment OCID out of the query string unless
// it is exactly one.
var compartmentPattern = regexp.MustCompile(`^ocid1\.compartment\.oc1\.\.[a-z0-9]+$`)

// CheckCompartment refuses any compartment value that is not an OCID.
func CheckCompartment(compartment string) error {
	if !compartmentPattern.MatchString(compartment) {
		return fmt.Errorf("compartment %q is not a compartment OCID", compartment)
	}
	return nil
}

func (t *OCITags) Resources(ctx context.Context) ([]Resource, error) {
	query := searchQuery
	if len(t.Compartments) > 0 {
		clauses := make([]string, 0, len(t.Compartments))
		for _, compartment := range t.Compartments {
			if err := CheckCompartment(compartment); err != nil {
				return nil, err
			}
			clauses = append(clauses, "compartmentId = '"+compartment+"'")
		}
		query += " && (" + strings.Join(clauses, " || ") + ")"
	}
	var resources []Resource
	var page *string
	for range maxSearchPages {
		response, err := t.search.SearchResources(ctx, resourcesearch.SearchResourcesRequest{
			SearchDetails: resourcesearch.StructuredSearchDetails{Query: common.String(query)},
			Limit:         common.Int(searchLimit),
			Page:          page,
		})
		if err != nil {
			return nil, fmt.Errorf("search OCI resources: %w", err)
		}
		for _, item := range response.Items {
			resources = append(resources, resourceOf(item))
		}
		if response.OpcNextPage == nil {
			return resources, nil
		}
		page = response.OpcNextPage
	}
	return nil, fmt.Errorf("OCI resource search returned more than %d pages", maxSearchPages)
}

func resourceOf(item resourcesearch.ResourceSummary) Resource {
	resource := Resource{ID: stringOf(item.Identifier), Type: stringOf(item.ResourceType),
		Name: stringOf(item.DisplayName), Compartment: stringOf(item.CompartmentId), Tags: item.FreeformTags}
	if item.TimeCreated != nil {
		resource.Created = item.TimeCreated.Time
	}
	return resource
}

func stringOf(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (t *OCITags) Retag(ctx context.Context, resource Resource, tags map[string]string) error {
	current, etag, write, err := t.load(ctx, resource)
	if err != nil {
		return fmt.Errorf("read OCI %s: %w", resource.Type, tagError(err))
	}
	merged := make(map[string]string, len(current)+len(tags))
	maps.Copy(merged, current)
	maps.Copy(merged, tags)
	if maps.Equal(merged, current) {
		return nil
	}
	if err := write(ctx, merged, etag); err != nil {
		return fmt.Errorf("update OCI %s tags: %w", resource.Type, tagError(err))
	}
	return nil
}

func (t *OCITags) load(ctx context.Context, resource Resource) (map[string]string, *string, tagWriter, error) {
	id := common.String(resource.ID)
	switch resource.Type {
	case "Instance":
		read, err := t.compute.GetInstance(ctx, core.GetInstanceRequest{InstanceId: id})
		return read.FreeformTags, read.Etag, func(ctx context.Context, tags map[string]string, etag *string) error {
			_, err := t.compute.UpdateInstance(ctx, core.UpdateInstanceRequest{InstanceId: id, IfMatch: etag,
				UpdateInstanceDetails: core.UpdateInstanceDetails{FreeformTags: tags}})
			return err
		}, err

	case "Bucket":
		namespace, err := t.namespaceName(ctx)
		if err != nil {
			return nil, nil, nil, err
		}
		// The bucket read carries no ETag in this SDK, so the write is not
		// conditional; the merge still keeps every tag the read returned.
		read, err := t.objects.GetBucket(ctx, objectstorage.GetBucketRequest{NamespaceName: common.String(namespace),
			BucketName: common.String(resource.Name)})
		return read.FreeformTags, nil, func(ctx context.Context, tags map[string]string, _ *string) error {
			_, err := t.objects.UpdateBucket(ctx, objectstorage.UpdateBucketRequest{NamespaceName: common.String(namespace),
				BucketName: common.String(resource.Name), UpdateBucketDetails: objectstorage.UpdateBucketDetails{FreeformTags: tags}})
			return err
		}, err
	}
	return nil, nil, nil, fmt.Errorf("no tag update for OCI type %q", resource.Type)
}

func (t *OCITags) namespaceName(ctx context.Context) (string, error) {
	if t.namespace != "" {
		return t.namespace, nil
	}
	response, err := t.objects.GetNamespace(ctx, objectstorage.GetNamespaceRequest{})
	if err != nil {
		return "", fmt.Errorf("read Object Storage namespace: %w", err)
	}
	if stringOf(response.Value) == "" {
		return "", errors.New("Object Storage namespace is empty")
	}
	t.namespace = *response.Value
	return t.namespace, nil
}

func tagError(err error) error {
	var service common.ServiceError
	if !errors.As(err, &service) {
		return err
	}
	switch service.GetHTTPStatusCode() {
	case http.StatusPreconditionFailed:
		return fmt.Errorf("%w: %w", ErrChanged, err)
	case http.StatusNotFound, http.StatusUnauthorized, http.StatusForbidden:
		return fmt.Errorf("%w: %w", ErrNotPermitted, err)
	}
	return err
}

func newStubTagger(api *stubTagAPI, connects *int) *Tagger {
	return &Tagger{Cell: "gru", Leader: func() bool { return true },
		Connect: func(context.Context) (TagAPI, error) { *connects++; return api, nil },
		Now:     func() time.Time { return tagsTestNow }}
}

type stubTagAPI struct {
	resources []Resource
	listErr   error
	retagErr  map[string]error
	retagged  []Resource
}

func (s *stubTagAPI) Resources(context.Context) ([]Resource, error) {
	return s.resources, s.listErr
}

func (s *stubTagAPI) Retag(_ context.Context, resource Resource, _ map[string]string) error {
	s.retagged = append(s.retagged, resource)
	return s.retagErr[resource.ID]
}

const passTimeout = 10 * time.Minute

// Tagger keeps the region's billable resources tagged with their region and
// component, so the Usage API can split their cost. Only the regional
// authority leader runs a pass.
type Tagger struct {
	Cell    string
	Leader  func() bool
	Connect func(ctx context.Context) (TagAPI, error)
	Now     func() time.Time

	api     TagAPI
	failure string
}

// Run tags once an hour until ctx ends, then returns nil.
func (t *Tagger) Run(ctx context.Context) error {
	for {
		timer := time.NewTimer(t.step(ctx))
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil
		case <-timer.C:
		}
	}
}

// step does one tag pass and returns how long to wait before the next.
func (t *Tagger) step(ctx context.Context) time.Duration {
	if !t.Leader() {
		return followInterval
	}
	if t.api == nil {
		api, err := t.Connect(ctx)
		if err != nil {
			t.fail(err)
			return retryInterval
		}
		t.api = api
	}
	passCtx, cancel := context.WithTimeout(ctx, passTimeout)
	result, err := Pass(passCtx, t.api, t.Cell, t.now())
	cancel()
	if err != nil {
		t.fail(err)
		return retryInterval
	}
	if result.Stamped+result.Changed+result.NotPermitted > 0 {
		slog.Info("OCI cost tag pass", observability.ComponentKey, "ocicost", "stamped", result.Stamped,
			"changed", result.Changed, "not_permitted", result.NotPermitted, "untagged", result.Untagged)
	}
	t.recovered()
	return Interval
}

// Pass plans and applies one pass with api.
func Pass(ctx context.Context, api TagAPI, cell string, now time.Time) (TagResult, error) {
	resources, err := api.Resources(ctx)
	if err != nil {
		return TagResult{}, fmt.Errorf("list OCI resources for tags: %w", err)
	}
	stamps, untagged := PlanTags(cell, resources, now)
	result, err := applyStamps(ctx, api, stamps)
	result.Untagged = len(untagged)
	return result, err
}

// applyStamps retags each planned resource. A resource that changed or that
// the principal may not update is counted, not fatal; any other error stops
// the pass with the counts so far.
func applyStamps(ctx context.Context, api TagAPI, stamps []Stamp) (TagResult, error) {
	var result TagResult
	for _, stamp := range stamps {
		switch err := api.Retag(ctx, stamp.Resource, stamp.Tags); {
		case errors.Is(err, ErrChanged):
			result.Changed++
		case errors.Is(err, ErrNotPermitted):
			result.NotPermitted++
		case err != nil:
			return result, fmt.Errorf("tag OCI %s %s: %w", stamp.Resource.Type, stamp.Resource.Name, err)
		default:
			result.Stamped++
		}
	}
	return result, nil
}

func (t *Tagger) now() time.Time {
	if t.Now == nil {
		return time.Now()
	}
	return t.Now()
}

// fail logs once per distinct error, so a long outage does not flood the log.
func (t *Tagger) fail(err error) {
	if err.Error() != t.failure {
		slog.Warn("OCI cost tags not applied", observability.ComponentKey, "ocicost", "error", err)
	}
	t.failure = err.Error()
}

func (t *Tagger) recovered() {
	if t.failure != "" {
		slog.Info("OCI cost tags are current again", observability.ComponentKey, "ocicost")
	}
	t.failure = ""
}

// Resource is one OCI resource a tag pass may stamp.
type Resource struct {
	ID          string
	Type        string // Resource Search type, e.g. "Instance", "BootVolume"
	Name        string
	Compartment string
	Created     time.Time
	Tags        map[string]string // freeform
}

// TaggedTypes are the billable resource types a pass stamps.
var TaggedTypes = []string{"Instance", "BootVolume", "Volume", "BootVolumeBackup", "VolumeBackup", "Image", "Bucket", "LoadBalancer"}

// Stamp is one resource's missing or wrong cost tags.
type Stamp struct {
	Resource Resource
	Tags     map[string]string // exactly RegionTag and ComponentTag
}

const (
	drSourceTag = "terrascale-dr-source"
	resourceTag = "terrascale-resource"
	roleTag     = "ts-role"
	appTag      = "terrascale-app"
	poolTag     = "ts-pool"
	// minTagAge keeps a pass away from resources still in their create flow,
	// whose ETag their creator may be holding.
	minTagAge = time.Hour
)

var controllerName = regexp.MustCompile(`^ts-[a-z]+-[0-9]+($|-| )`)

// Component infers a resource's component from the marks it already has,
// or "" when none fits; the pass never guesses.
func Component(cell string, r Resource) string {
	if component := r.Tags[ComponentTag]; slices.Contains(Components, component) {
		return component
	}
	if _, ok := r.Tags[drSourceTag]; ok {
		return "disaster-recovery"
	}
	switch mark := r.Tags[resourceTag]; {
	case strings.HasPrefix(mark, "member-") || mark == "terrabase-host":
		return "terrabase"
	case mark == "managed-volume":
		return "apps"
	}
	if r.Tags[roleTag] == "db" {
		return "terrabase"
	}
	if r.Tags[appTag] != "" {
		return "apps"
	}
	if r.Tags[poolTag] != "" {
		return "node-pool"
	}
	switch r.Type {
	case "Instance", "BootVolume", "Volume", "BootVolumeBackup", "VolumeBackup":
		name := strings.TrimSuffix(r.Name, " (Boot Volume)")
		switch {
		case strings.Contains(name, "-ctl-") || controllerName.MatchString(name):
			return "controller"
		case strings.Contains(name, "-db-") || strings.HasPrefix(name, "ts-member-data-backup-"):
			return "terrabase"
		case strings.Contains(name, "-pool-"):
			return "node-pool"
		}
	case "Bucket":
		if !strings.HasPrefix(r.Name, cell+"-") {
			return "storage"
		}
		switch {
		case strings.HasSuffix(r.Name, "-backup"):
			return "terrabase"
		case strings.HasSuffix(r.Name, "-head"):
			return "releases"
		case strings.HasSuffix(r.Name, "-material") || strings.HasSuffix(r.Name, "-ledger"):
			return "controller"
		}
		return "storage"
	case "Image":
		return "images"
	case "LoadBalancer":
		return "network"
	}
	return ""
}

// PlanTags returns the stamps the cell's resources need at now, and the
// resources no rule fits.
func PlanTags(cell string, resources []Resource, now time.Time) (stamps []Stamp, untagged []Resource) {
	for _, r := range resources {
		if !slices.Contains(TaggedTypes, r.Type) || !r.Created.IsZero() && now.Sub(r.Created) < minTagAge {
			continue
		}
		component := Component(cell, r)
		if component == "" {
			untagged = append(untagged, r)
			continue
		}
		region := strings.ToUpper(cell)
		if r.Tags[RegionTag] == region && r.Tags[ComponentTag] == component {
			continue
		}
		stamps = append(stamps, Stamp{Resource: r, Tags: map[string]string{RegionTag: region, ComponentTag: component}})
	}
	return stamps, untagged
}

const (
	// Interval is how often the leader reads OCI usage.
	Interval       = time.Hour
	retryInterval  = 5 * time.Minute
	followInterval = time.Minute
	readTimeout    = 2 * time.Minute
)

// usageTenancyProvider answers only the tenancy, the one call Connect makes
// before it needs the network.
type usageTenancyProvider struct {
	common.ConfigurationProvider
	err error
}

func (p usageTenancyProvider) TenancyOCID() (string, error) { return "", p.err }

func Connect(ctx context.Context, factory *ociclient.Factory, cell, ociRegion string) (*Usage, error) {
	tenancy, err := factory.Provider().TenancyOCID()
	if err != nil {
		return nil, fmt.Errorf("read the tenancy: %w", err)
	}
	if tenancy == "" {
		return nil, errors.New("principal has no tenancy")
	}
	home, err := factory.HomeRegion(ctx, tenancy)
	if err != nil {
		return nil, err
	}
	client, err := factory.Usage()
	if err != nil {
		return nil, err
	}
	client.SetRegion(home)
	return &Usage{Cell: cell, OCIRegion: ociRegion, TenancyID: tenancy, API: client}, nil
}

func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}

func (o RetryOptions) normalized() RetryOptions {
	if o.MaxAttempts == 0 {
		o.MaxAttempts = defaultMaxAttempts
	}
	if o.BaseDelay <= 0 {
		o.BaseDelay = defaultBaseDelay
	}
	if o.MaxDelay <= 0 {
		o.MaxDelay = defaultMaxDelay
	}
	if o.MaxDelay < o.BaseDelay {
		o.MaxDelay = o.BaseDelay
	}
	if o.Jitter == nil {
		o.Jitter = rand.Float64
	}
	return o
}

func RetryPolicy(options RetryOptions) common.RetryPolicy {
	options = options.normalized()
	return common.NewRetryPolicy(options.MaxAttempts, ShouldRetry, func(response common.OCIOperationResponse) time.Duration {
		return retryDelay(options, response)
	})
}
